SELECT cu.customer_id, cu.company_name
FROM customers cu
WHERE NOT EXISTS (
    SELECT 1 FROM orders o WHERE o.customer_id = cu.customer_id
);

SELECT p.product_id, p.product_name
FROM products p
WHERE NOT EXISTS (
    SELECT 1 FROM order_details od WHERE od.product_id = p.product_id
);

SELECT o.order_id, c.contact_name
FROM orders o
LEFT JOIN customers c ON c.customer_id = o.customer_id;

SELECT CONCAT(e.first_name, ' ', e.last_name) AS employee_name
FROM employees e
WHERE NOT EXISTS (
    SELECT 1 FROM employees m WHERE m.employee_id = e.reports_to
);

SELECT CONCAT(e.first_name, ' ', e.last_name) AS employee_name,
       c.category_name
FROM employees e, categories c;
